// TypeScript port of scoring/prompt_guess_scoring (scorer v3). Keep in step with the Python:
// tables come from keywords.json, regenerated by `python scoring/export_ts_data.py`.
import tables from "./keywords.json";
import paramsJson from "../../scoring/prompt_guess_scoring/params.json";

export interface Params {
  cos_lo: number; cos_hi: number; gamma: number; kw_weight: number; version: number;
  thresholds: { great: number; close: number; partial: number };
}
export const PARAMS: Params = paramsJson as Params;
export type Bucket = "great" | "close" | "partial" | "miss";

const STOP = new Set<string>(tables.stopwords);
const SYN1: Record<string, string> = tables.synonyms_v1;
const SYN2: Record<string, string> = { ...tables.synonyms_v2 };

/** Merge puzzle-specific synonym groups (private data) into the v2 table, as the Python does. */
export function addSynonymGroups(groups: string[][]): void {
  for (const g of groups) {
    const c = has(SYN2, g[0]) ? SYN2[g[0]] : g[0];
    for (const w of g) SYN2[w] = c;
  }
}
const IRREG: Record<string, string> = tables.irregular;
const has = (o: Record<string, string>, k: string) => Object.prototype.hasOwnProperty.call(o, k);

export function lemma(word: string): string {
  const w = word.toLowerCase();
  if (has(IRREG, w)) return IRREG[w];
  if (has(SYN1, w)) return w;
  const sufs: [string, string][] = [["ies", "y"], ["ves", "f"], ["sses", "ss"], ["ches", "ch"], ["shes", "sh"], ["xes", "x"]];
  for (const [suf, rep] of sufs) {
    if (w.endsWith(suf) && w.length > suf.length + 2) return w.slice(0, -suf.length) + rep;
  }
  if (w.endsWith("ing") && w.length > 5) {
    let base = w.slice(0, -3);
    if (base.length > 2 && base[base.length - 1] === base[base.length - 2]) base = base.slice(0, -1);
    return base;
  }
  if (w.endsWith("ed") && w.length > 4) return w.slice(0, -2);
  if (w.endsWith("s") && !/(ss|us|is)$/.test(w) && w.length > 3) return w.slice(0, -1);
  return w;
}

export function canonical(word: string, syn: Record<string, string> = SYN1): string {
  const w = word.toLowerCase();
  if (has(syn, w)) return syn[w];
  const l = lemma(w);
  return has(syn, l) ? syn[l] : l;
}

export function contentWords(text: string): string[] {
  return (text.toLowerCase().match(/[a-z]+/g) ?? []).filter((t) => !STOP.has(t) && t.length > 1);
}

export function keywordMatch(answer: string, guess: string, version = 1): { recall: number; matched: string[] } {
  const ans = contentWords(answer);
  if (!ans.length) return { recall: 0, matched: [] };
  const syn = version >= 2 ? SYN2 : SYN1;
  const g = new Set(contentWords(guess).map((t) => canonical(t, syn)));
  const matched: string[] = [], seen = new Set<string>();
  for (const t of ans) {
    const c = canonical(t, syn);
    if (seen.has(c)) continue;
    seen.add(c);
    if (g.has(c)) matched.push(t);
  }
  return { recall: matched.length / seen.size, matched };
}

export function semanticScore(cos: number, p: Params = PARAMS): number {
  const x = Math.min(Math.max((cos - p.cos_lo) / (p.cos_hi - p.cos_lo), 0), 1);
  return 100 * x ** p.gamma;
}

export function combine(cos: number, recall: number, p: Params = PARAMS): number {
  const s = (1 - p.kw_weight) * semanticScore(cos, p) + p.kw_weight * 100 * recall;
  return Math.round(Math.min(Math.max(s, 0), 100) * 10) / 10;
}

export function bucket(score: number, p: Params = PARAMS): Bucket {
  const t = p.thresholds;
  return score >= t.great ? "great" : score >= t.close ? "close" : score >= t.partial ? "partial" : "miss";
}

export function cosine(a: number[], b: number[]): number {
  let d = 0, na = 0, nb = 0;
  for (let i = 0; i < a.length; i++) { d += a[i] * b[i]; na += a[i] * a[i]; nb += b[i] * b[i]; }
  return d / (Math.sqrt(na * nb) || 1);
}

export interface ScoreResult { score: number; bucket: Bucket; matched: string[] }

export function scoreFromCosine(answer: string, guess: string, cos: number, p: Params = PARAMS): ScoreResult {
  if (!guess.trim()) return { score: 0, bucket: "miss", matched: [] };
  const { recall, matched } = keywordMatch(answer, guess, p.version);
  const s = combine(cos, recall, p);
  return { score: s, bucket: bucket(s, p), matched };
}

/** The answer as display tokens; `hit` marks words the guesses have matched. */
export function maskAnswer(answer: string, matched: Iterable<string>): { word: string; hit: boolean; content: boolean }[] {
  const syn = PARAMS.version >= 2 ? SYN2 : SYN1;
  const hits = new Set([...matched].map((m) => canonical(m, syn)));
  return answer.split(/\s+/).filter(Boolean).map((tok) => {
    const core = tok.toLowerCase().replace(/[^a-z]/g, "");
    const content = !!core && !STOP.has(core) && core.length > 1;
    return { word: tok, content, hit: !content || hits.has(canonical(core, syn)) };
  });
}
